"use client";

import { useEffect, useMemo, useState, type ReactNode } from "react";
import { Combobox, type ComboboxOption } from "./combobox";
import { FormField } from "./form-field";
import { useLocale, useT } from "@/i18n/client";
import { INTL_LOCALE } from "@/i18n/config";

/** [iso2, englishName, hasRegions] — generated by scripts/build-geo.py into /public/geo. */
type CountryRow = [string, string, boolean];
/** [regionCode, regionName, cities] */
type RegionRow = [string, string, string[]];

// Static, CDN-cached files; memoized per session so switching forms doesn't refetch.
const cache = new Map<string, Promise<unknown>>();
function load<T>(path: string): Promise<T> {
  if (!cache.has(path)) {
    const p = fetch(path).then((r) => (r.ok ? r.json() : Promise.reject(new Error(`${path}: ${r.status}`))));
    p.catch(() => cache.delete(path));
    cache.set(path, p);
  }
  return cache.get(path) as Promise<T>;
}

const norm = (s: string) => s.normalize("NFD").replace(/\p{Diacritic}/gu, "").toLocaleLowerCase().trim();

export type LocationValue = { country: string; region: string; city: string };

/**
 * Country → province/state → city, linked and world-wide. Posts `locationCountry` (ISO 3166-1
 * alpha-2), `locationRegion` (ISO 3166-2 subdivision code, e.g. "ON", which matching compares by
 * equality) and `locationCity`. Cities missing from the dataset can still be typed in.
 */
export function LocationFields({
  defaults,
  labels,
  errors,
  badges,
}: {
  defaults: Partial<LocationValue>;
  labels: { country: string; region: string; city: string };
  errors?: { country?: string | string[]; region?: string | string[]; city?: string | string[] };
  badges?: { country?: ReactNode; region?: ReactNode; city?: ReactNode };
}) {
  const t = useT("common");
  const locale = useLocale();
  const [country, setCountry] = useState((defaults.country ?? "").toUpperCase());
  const [region, setRegion] = useState(defaults.region ?? "");
  const [city, setCity] = useState(defaults.city ?? "");
  const [countries, setCountries] = useState<CountryRow[] | null>(null);
  const [regions, setRegions] = useState<{ country: string; rows: RegionRow[] } | null>(null);

  useEffect(() => {
    let live = true;
    load<CountryRow[]>("/geo/countries.json").then((rows) => live && setCountries(rows)).catch(() => live && setCountries([]));
    return () => {
      live = false;
    };
  }, []);

  useEffect(() => {
    if (!/^[A-Z]{2}$/.test(country)) return;
    let live = true;
    load<RegionRow[]>(`/geo/${country}.json`)
      .then((rows) => {
        if (!live) return;
        setRegions({ country, rows });
        // Imported / legacy values may hold the region's name ("Ontario"): map it to its code.
        setRegion((r) => (r && !rows.some(([code]) => code === r) ? (rows.find(([code, name]) => norm(name) === norm(r) || norm(code) === norm(r))?.[0] ?? r) : r));
      })
      .catch(() => live && setRegions({ country, rows: [] }));
    return () => {
      live = false;
    };
  }, [country]);

  const countryOptions = useMemo<ComboboxOption[]>(() => {
    if (!countries) return country ? [{ value: country, label: country }] : [];
    let names: Intl.DisplayNames | null = null;
    try {
      names = new Intl.DisplayNames([INTL_LOCALE[locale]], { type: "region" });
    } catch {}
    return countries
      .map(([code, en]) => ({ value: code, label: names?.of(code) ?? en }))
      .sort((a, b) => a.label.localeCompare(b.label, INTL_LOCALE[locale]));
  }, [countries, country, locale]);

  const regionRows = regions?.country === country ? regions.rows : null;
  const regionOptions = useMemo<ComboboxOption[]>(() => {
    const opts = (regionRows ?? []).map(([code, name]) => ({ value: code, label: name }));
    // Keep a stored value that isn't in the dataset selectable rather than silently dropping it.
    if (region && !opts.some((o) => o.value === region)) opts.unshift({ value: region, label: region });
    return opts;
  }, [regionRows, region]);

  const cityOptions = useMemo<ComboboxOption[]>(() => {
    const list = regionRows?.find(([code]) => code === region)?.[2] ?? [];
    return list.map((c) => ({ value: c, label: c }));
  }, [regionRows, region]);

  const loadingRegions = !!country && !regionRows;
  const hasRegions = !!regionRows?.length;
  const common = { searchPlaceholder: t("location.search"), emptyText: t("location.noResults"), moreText: t("location.more") };

  return (
    <div className="grid gap-4 sm:grid-cols-3">
      <FormField id="locationCountry" label={labels.country} error={errors?.country} badge={badges?.country}>
        <Combobox
          {...common}
          id="locationCountry"
          name="locationCountry"
          value={country}
          onChange={(v) => {
            if (v === country) return;
            setCountry(v);
            setRegion("");
            setCity("");
          }}
          options={countryOptions}
          placeholder={t("location.selectCountry")}
          loading={!countries}
          invalid={!!errors?.country}
        />
      </FormField>
      <FormField id="locationRegion" label={labels.region} error={errors?.region} badge={badges?.region}>
        <Combobox
          {...common}
          id="locationRegion"
          name="locationRegion"
          value={region}
          onChange={(v) => {
            if (v === region) return;
            setRegion(v);
            setCity("");
          }}
          options={regionOptions}
          placeholder={!country ? t("location.selectCountryFirst") : loadingRegions || hasRegions ? t("location.selectRegion") : t("location.noRegions")}
          disabled={!country || (!loadingRegions && !hasRegions && !region)}
          loading={loadingRegions}
          invalid={!!errors?.region}
        />
      </FormField>
      <FormField id="locationCity" label={labels.city} error={errors?.city} badge={badges?.city}>
        <Combobox
          {...common}
          id="locationCity"
          name="locationCity"
          value={city}
          onChange={setCity}
          options={cityOptions}
          placeholder={!country ? t("location.selectCountryFirst") : hasRegions && !region ? t("location.selectRegionFirst") : t("location.selectCity")}
          disabled={!country || (hasRegions && !region && !city)}
          allowCustom
          customLabel={(q) => t("location.useCustom", { value: q })}
          invalid={!!errors?.city}
        />
      </FormField>
    </div>
  );
}
